/bin/bash -lc "python3 - <<'PY'
import json
j=json.load(open('ensembl_species.json'))
wanted=['pan_troglodytes','macaca_mulatta','pan_paniscus','indri_indri','semnopithecus_johnii','ailuropoda_melanoleuca','delphinapterus_leucas']
sp={s['name']:s for s in j['species']}
for w in wanted:
    print(w, 'FOUND' if w in sp else 'MISSING')
    if w in sp:
        print(sp[w].get('display_name'), sp[w].get('assembly'), sp[w].get('division'))
PY"
